    [Serializable] public class GameSettings {public float master=.8f,music=.55f,sfx=.85f,ui=1;public bool reducedMotion,touch;}
    public sealed class DenTinhGame : MonoBehaviour {
        public Simulation Game;ContentDatabase content;Camera view;Texture2D keyArt;Font font;Material material;AudioSource audioSource,musicSource;AudioClip[] notes;
        readonly Dictionary<string,SpriteRenderer> sprites=new Dictionary<string,SpriteRenderer>();readonly Dictionary<string,LineRenderer> lines=new Dictionary<string,LineRenderer>();readonly HashSet<string> visible=new HashSet<string>();readonly HashSet<Effect> playedFx=new HashSet<Effect>();
        GameSettings settings=new GameSettings();string selected="an",screen="menu",dialogue="",toast="",lastZone="";float toastTime,saveTime,musicTime,rStarted=-1;bool rHeld;int musicNote;Sprite terrain;GUIStyle text,title,small,button,card;bool stylesReady;int moveFinger=-1,aimFinger=-1,rFinger=-1;Vector2 moveOrigin,aimOrigin,moveTouch,aimTouch;bool touchFire;
        string SaveFolder {get{return Path.Combine(Path.GetDirectoryName(Application.dataPath),"Saves");}}string SavePath {get{return Path.Combine(SaveFolder,"unity-save.json");}}
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)] static void Boot(){if(FindFirstObjectByType<DenTinhGame>()==null)new GameObject("Đèn Tinh · Game").AddComponent<DenTinhGame>();}
        void Awake(){
            content=CatalogData.Create();Application.targetFrameRate=60;QualitySettings.vSyncCount=1;keyArt=Resources.Load<Texture2D>("Art/KeyArt");font=Font.CreateDynamicFontFromOSFont("Segoe UI",20);Shader shader=Resources.Load<Shader>("PixelSprite");material=new Material(shader!=null?shader:Shader.Find("Sprites/Default"));PixelArt.Material=material;
            GameObject cameraObject=new GameObject("Main Camera");view=cameraObject.AddComponent<Camera>();view.orthographic=true;view.orthographicSize=Screen.height/128f;view.backgroundColor=PixelArt.ColorOf("#102936");view.transform.position=new Vector3(11.5f,10,-20);cameraObject.AddComponent<AudioListener>();
            audioSource=gameObject.AddComponent<AudioSource>();musicSource=gameObject.AddComponent<AudioSource>();audioSource.playOnAwake=musicSource.playOnAwake=false;notes=new AudioClip[16];for(int i=0;i<notes.Length;i++)notes[i]=Tone(110*Mathf.Pow(2,i/12f),.9f,.22f,false);
            try{string p=Path.Combine(SaveFolder,"settings.json");if(File.Exists(p))settings=JsonUtility.FromJson<GameSettings>(File.ReadAllText(p))??settings;}catch(Exception e){Debug.LogWarning(e.Message);}
            if(Application.isMobilePlatform)settings.touch=true;NewGame("an",0,false);screen="menu";Game.Paused=true;
        }
        void NewGame(string hero,int cycle,bool play){selected=hero;Game=new Simulation(content,hero,Environment.TickCount&int.MaxValue,cycle);terrain=MakeGround();view.transform.position=new Vector3(Game.Player.position.x,Game.Player.position.y,-20);screen=play?"":"menu";Game.Paused=!play;saveTime=0;playedFx.Clear();enemyVisuals.Clear();if(play){dialogue="Sương nuốt mất tên của Làng Đèn. Bà Năm trao cho con một ngọn đèn còn nhớ đường về.\n\nSăn Trúc Vệ, giữ Đèn Sen và thanh tẩy lò Tro. Đốm và HoaVi sẽ cùng con tìm những ký ức cũ.";screen="dialogue";Game.Paused=true;}}
        void Update(){
            if(Game==null)return;float dt=Mathf.Min(.04f,Time.unscaledDeltaTime);toastTime=Mathf.Max(0,toastTime-dt);
            audioSource.volume=settings.master*settings.sfx;musicSource.volume=settings.master*settings.music*.5f;
            if(Input.GetKeyDown(KeyCode.Escape)){if(screen=="")Open("pause");else if(screen!="menu"&&screen!="death"&&screen!="talent"&&screen!="victory")Resume();}
            if(screen==""){
                Vector2 move=new Vector2((Input.GetKey(KeyCode.D)?1:0)-(Input.GetKey(KeyCode.A)?1:0),(Input.GetKey(KeyCode.W)?1:0)-(Input.GetKey(KeyCode.S)?1:0));move+=new Vector2((Input.GetKey(KeyCode.RightArrow)?1:0)-(Input.GetKey(KeyCode.LeftArrow)?1:0),(Input.GetKey(KeyCode.UpArrow)?1:0)-(Input.GetKey(KeyCode.DownArrow)?1:0));
                Vector3 aim=view.ScreenToWorldPoint(Input.mousePosition);ReadTouch();if(moveTouch.sqrMagnitude>.01f)move=moveTouch;V2 target=touchFire?Game.Player.position+new V2(aimTouch.x,aimTouch.y)*7:new V2(aim.x,aim.y);Game.Input=new GameInput{move=new V2(move.x,move.y),aim=target,attack=Input.GetMouseButton(0)&&Input.mousePosition.y>160||touchFire};
                if(Input.GetKeyDown(KeyCode.Space))Game.Dash();if(Input.GetKeyDown(KeyCode.Q))Game.Skill("q");if(Input.GetKeyDown(KeyCode.E))Game.Skill("e");if(Input.GetKeyDown(KeyCode.R)){if(Game.IsElemental){rStarted=Time.unscaledTime;rHeld=false;}else Game.Skill("r");}if(Game.IsElemental){if(rStarted>=0&&(Input.GetKey(KeyCode.R)||rFinger>=0)&&Time.unscaledTime-rStarted>=.45f&&!rHeld){rHeld=true;if(Game.SplitTime<=0)Game.SplitElementals(7);}if(Input.GetKeyUp(KeyCode.R)&&rStarted>=0){rStarted=-1;if(!rHeld)Open("split");}for(int i=0;i<7;i++)if(Input.GetKeyDown((KeyCode)((int)KeyCode.Alpha1+i)))Game.TransformElement(content.elements[i].id);if(Input.GetKeyDown(KeyCode.X))Game.SplitElementals(Game.Player.splitCount);if(Input.GetKeyDown(KeyCode.G))Game.Player.splitCount=Game.Player.splitCount==3?5:Game.Player.splitCount==5?7:3;if(Input.GetKeyDown(KeyCode.C))Open("elements");}if(Input.GetKeyDown(KeyCode.H))Game.Heal();if(Input.GetKeyDown(KeyCode.Tab))Game.Swap();if(Input.GetKeyDown(KeyCode.V))Game.Reload();if(Input.GetKeyDown(KeyCode.F))Game.Interact();if(Input.GetKeyDown(KeyCode.I))Open("inventory");if(Input.GetKeyDown(KeyCode.M))Open("map");
            }else{moveTouch=Vector2.zero;touchFire=false;}
            Game.Tick(dt);ProcessEvents();if(Game.PendingLevels>0&&screen=="")Open("talent");
            if(screen!="menu"){saveTime+=dt;if(saveTime>=12){saveTime=0;Save();}}
            view.orthographicSize=Screen.height/128f;Vector3 p=new Vector3(Game.Player.position.x,Game.Player.position.y,-20);float halfW=view.orthographicSize*view.aspect;p.x=Mathf.Clamp(p.x,halfW,Simulation.Width-halfW);p.y=Mathf.Clamp(p.y,view.orthographicSize,Simulation.Height-view.orthographicSize);view.transform.position=Vector3.Lerp(view.transform.position,p,1-Mathf.Exp(-7*dt));if(!settings.reducedMotion&&Game.Shake>0)view.transform.position+=(Vector3)UnityEngine.Random.insideUnitCircle*Game.Shake*.05f;
            Vector3 snapped=view.transform.position;snapped.x=Mathf.Round(snapped.x*64)/64;snapped.y=Mathf.Round(snapped.y*64)/64;view.transform.position=snapped;Render();Music(dt);
        }
        void ReadTouch(){
            if(!settings.touch)return;Rect splitTouch=new Rect(895f/1600*Screen.width,41f/900*Screen.height,135f/1600*Screen.width,96f/900*Screen.height);foreach(Touch t in Input.touches){
                if(Game.IsElemental&&t.phase==TouchPhase.Began&&splitTouch.Contains(t.position)){rFinger=t.fingerId;rStarted=Time.unscaledTime;rHeld=false;continue;}
                if(t.fingerId==rFinger){if(t.phase==TouchPhase.Ended||t.phase==TouchPhase.Canceled){rFinger=-1;bool tap=t.phase==TouchPhase.Ended&&rStarted>=0&&!rHeld;rStarted=-1;if(tap)Open("split");}continue;}
                if(t.phase==TouchPhase.Began&&t.position.y<Screen.height*.55f){if(t.position.x<Screen.width*.35f&&moveFinger<0){moveFinger=t.fingerId;moveOrigin=t.position;}else if(t.position.x>Screen.width*.72f&&aimFinger<0){aimFinger=t.fingerId;aimOrigin=t.position;}}
                if(t.fingerId==moveFinger)moveTouch=Vector2.ClampMagnitude((t.position-moveOrigin)/65,1);if(t.fingerId==aimFinger){aimTouch=Vector2.ClampMagnitude((t.position-aimOrigin)/65,1);touchFire=aimTouch.magnitude>.15f;}
                if(t.phase==TouchPhase.Ended||t.phase==TouchPhase.Canceled){if(t.fingerId==moveFinger){moveFinger=-1;moveTouch=Vector2.zero;}if(t.fingerId==aimFinger){aimFinger=-1;touchFire=false;}}
            }
        }
        void ProcessEvents(){while(Game.Events.Count>0){SimEvent e=Game.Events.Dequeue();if(e.kind=="sound"){Sfx(e.text);continue;}if(e.kind=="save"){Save();continue;}if(e.kind=="death"){Open("death");continue;}if(e.kind=="victory"){Save();Open("victory");continue;}if(e.kind=="shop"){Open("shop");continue;}if(e.kind=="dialogue"||e.kind=="memory"){dialogue=e.text;Open("dialogue");continue;}if(e.kind=="level")continue;toast=e.text;toastTime=4.5f;}}
        void Open(string name){screen=name;Game.Paused=true;touchFire=false;moveTouch=Vector2.zero;rStarted=-1;rFinger=-1;}
        void Resume(){screen="";Game.Paused=false;if(Game.PendingLevels>0)Open("talent");Save();}
        public void Save(){if(Game==null||Game.Dead||screen=="menu")return;try{Directory.CreateDirectory(SaveFolder);string tmp=SavePath+".tmp";File.WriteAllText(tmp,JsonUtility.ToJson(Game.Capture(),true));if(File.Exists(SavePath))File.Copy(SavePath,SavePath+".bak",true);File.Copy(tmp,SavePath,true);File.Delete(tmp);}catch(Exception e){toast="Chưa lưu được: "+e.Message;toastTime=5;Debug.LogError(e);}}
        void Continue(){try{RunSave data=JsonUtility.FromJson<RunSave>(File.ReadAllText(SavePath));Game=Simulation.Restore(content,data);selected=Game.Hero.id;enemyVisuals.Clear();terrain=MakeGround();screen="";Game.Paused=false;toast="Ngọn đèn vẫn đợi bạn.";toastTime=3;}catch(Exception e){toast="Bản lưu chưa đọc được: "+e.Message;toastTime=6;}}
        void OnApplicationFocus(bool focused){if(!focused){rStarted=-1;rFinger=-1;rHeld=false;if(Game!=null&&screen==""){Open("pause");Save();}}}
        void OnApplicationQuit(){Save();}
        void OnApplicationPause(bool paused){if(paused&&Game!=null){if(screen=="")Open("pause");Save();}}
        SpriteRenderer Show(string id,Sprite sprite,V2 at,float scale,Color color,int order){visible.Add(id);SpriteRenderer r;if(!sprites.TryGetValue(id,out r)){GameObject o=new GameObject(id);o.transform.SetParent(transform);r=o.AddComponent<SpriteRenderer>();r.sharedMaterial=material;sprites[id]=r;}r.gameObject.SetActive(true);r.sprite=sprite;r.color=color;r.sortingOrder=order;r.transform.position=new Vector3(Mathf.Round(at.x*64)/64,Mathf.Round(at.y*64)/64,0);r.transform.localScale=Vector3.one*scale;r.transform.rotation=Quaternion.identity;return r;}
        void Ring(string id,V2 at,float radius,Color color,float progress=1){visible.Add(id);LineRenderer r;if(!lines.TryGetValue(id,out r)){GameObject o=new GameObject(id);o.transform.SetParent(transform);r=o.AddComponent<LineRenderer>();r.sharedMaterial=material;r.useWorldSpace=true;r.loop=false;r.widthMultiplier=.035f;r.sortingOrder=3200;lines[id]=r;}r.gameObject.SetActive(true);r.positionCount=49;r.startColor=r.endColor=color;for(int i=0;i<49;i++){float a=i/48f*Mathf.PI*2*progress;r.SetPosition(i,new Vector3(at.x+Mathf.Cos(a)*radius,at.y+Mathf.Sin(a)*radius,-.1f));}}
        bool InView(V2 p){return Mathf.Abs(p.x-view.transform.position.x)<view.orthographicSize*view.aspect+3&&Mathf.Abs(p.y-view.transform.position.y)<view.orthographicSize+4;}
        int Order(V2 p){return 1500-(int)(p.y*20);}
        sealed class EnemyVisual {public V2 position;public float cooldown,attack=-100;}
        readonly Dictionary<EnemyState,EnemyVisual> enemyVisuals=new Dictionary<EnemyState,EnemyVisual>();
        void DrawEnemy(EnemyState e){
            EnemyVisual previous;if(!enemyVisuals.TryGetValue(e,out previous))previous=new EnemyVisual{position=e.position,cooldown=e.cooldown};
            bool moving=V2.Distance(previous.position,e.position)>.0005f,boss=e.type.StartsWith("boss");if(e.cooldown>previous.cooldown+.4f)previous.attack=Game.Time;
            bool attacking=Game.Time-previous.attack<.55f||e.type=="boar"&&e.phase>0;string pose=e.hit>0&&!boss?"hit":attacking?(boss?(e.pattern%3==0?"cast_rage":"attack_slam"):"attack"):moving?(boss?"move":"walk"):"idle";
            float age=e.hit>0?.18f-e.hit:attacking?Game.Time-previous.attack:Game.Time;SpriteRenderer r=Show(e.id,PixelArt.Actor(e.type,pose,age,settings.reducedMotion),e.position+new V2(0,e.throwLift),1,Color.white,Order(e.position));r.flipX=!boss&&e.type!="slime"&&Game.Player.position.x<e.position.x;
            previous.position=e.position;previous.cooldown=e.cooldown;enemyVisuals[e]=previous;
            if(e.burn>0)Show("burn-"+e.id,PixelArt.World("flame",Game.Time,settings.reducedMotion),e.position,1,Color.white,Order(e.position)+1);
            if(e.miniBoss){Show(e.id+"-crown",PixelArt.Vfx("crest_lightning",Game.Time,settings.reducedMotion),e.position+new V2(0,1.5f),1,Color.white,Order(e.position)+2);}
        }
        void DrawWorld(){
            for(int i=0;i<Game.Decals.Count;i++){GroundDecal d=Game.Decals[i];if(!InView(d.position))continue;string key=d.type=="scorch_mark"?d.type+"/"+d.size:d.type;Show("decal-"+i,PixelArt.World(key,Game.Time,settings.reducedMotion),d.position,1,new Color(1,1,1,Mathf.Min(1,(d.life-d.age)/4)),-900);
                if(!settings.reducedMotion&&d.type=="scorch_mark"&&d.age<4.5f)Show("ember-"+i,PixelArt.World("flame",Game.Time+i*.1f),d.position,1,new Color(1,1,1,.55f),-899);
                if(!settings.reducedMotion&&d.type=="lightning_scar"&&d.age<3)Show("scar-"+i,PixelArt.Vfx("crest_lightning",Game.Time),d.position,1,Color.white,-899);
            }
            for(int i=0;i<Game.Props.Count;i++){Prop p=Game.Props[i];if(!InView(p.position)||Game.Summons.Exists(s=>s.sourceProp==p))continue;Color tint=Color.white;V2 at=Game.Player.position;if(p.damageStage<2&&at.y>p.position.y&&at.y<p.position.y+2&&Mathf.Abs(at.x-p.position.x)<.9f)tint.a=.45f;
                SpriteRenderer r=Show("prop-"+i,PixelArt.WorldProp(p,Game.Time,settings.reducedMotion),p.position,1,tint,Order(p.position));if(!settings.reducedMotion&&p.damageStage<2&&p.status!="frozen")r.transform.rotation=Quaternion.Euler(0,0,p.sway*Mathf.Sin(Game.Time*16)*20);
                if(p.status=="burning"){for(int k=0;k<3;k++)Show("prop-fire-"+i+"-"+k,PixelArt.World("flame",Game.Time+k*.1f,settings.reducedMotion),p.position+new V2((k-1)*.3f,.25f+k*.4f),1,Color.white,Order(p.position)+1);Show("prop-smoke-"+i,PixelArt.World("steam_cloud",Game.Time,settings.reducedMotion),p.position+new V2(0,1.5f),1,new Color(.22f,.19f,.25f,.7f),Order(p.position)+2);}
                else if(p.status=="charred")Show("prop-smoke-"+i,PixelArt.World("steam_cloud",Game.Time,settings.reducedMotion),p.position+new V2(0,1.2f),1,new Color(.4f,.4f,.45f,.25f),Order(p.position)+1);
            }
        }
