            DrawWorld();RenderShadows();foreach(StoryNpc npc in Simulation.StoryNpcs)if(InView(npc.position))Show(npc.id,PixelArt.Actor(npc.id,"idle",Game.Time,settings.reducedMotion),npc.position,1,Color.white,Order(npc.position));
            Show("elder",PixelArt.Actor("elder","idle",Game.Time,settings.reducedMotion),new V2(10.5f,11),1,Color.white,Order(new V2(10.5f,11)));Show("smith",PixelArt.Actor("smith","idle",Game.Time,settings.reducedMotion),new V2(14.5f,8.5f),1,Color.white,Order(new V2(14.5f,8.5f)));Show("well",PixelArt.Item("shrine"),new V2(8.2f,8.6f),.7f,PixelArt.ColorOf("#93d6dc"),1300);
            foreach(Shrine s in Game.Shrines)if(InView(s.position)){Color col=PixelArt.ColorOf(s.active?"#9ef1bd":s.id=="sen"?"#f4b1d7":s.id=="tro"?"#ffd098":"#addfbc");Show("shrine-"+s.id,PixelArt.Item("shrine"),s.position,1.25f,col,Order(s.position));Show("glow-"+s.id,PixelArt.Glow(),s.position+new V2(0,.6f),2,new Color(col.r,col.g,col.b,.25f),1900);if(s.started&&!s.complete)Ring("challenge-"+s.id,s.position,3.6f,new Color(col.r,col.g,col.b,.6f));}
            foreach(Loot l in Game.Drops)if(!l.collected&&InView(l.position)){Sprite item=l.kind=="weapon"?PixelArt.Weapon(content.Weapon(l.weapon)):l.kind=="chest"?PixelArt.Item("chest"):l.kind=="memory"?PixelArt.Item("core"):PixelArt.Dot();Color col=l.kind=="weapon"?PixelArt.ColorOf(content.Weapon(l.weapon).color):l.kind=="gold"?PixelArt.ColorOf("#f3cc7b"):l.kind=="potion"?PixelArt.ColorOf("#efa3be"):Color.white;float scale=l.kind=="gold"||l.kind=="potion"?.7f:l.kind=="memory"?.5f:1;Show(l.id,item,l.position+new V2(0,Mathf.Sin(Game.Time*3+l.position.x)*.04f),scale,col,Order(l.position));}
            foreach(EnemyState e in Game.Enemies)if(e.alive&&InView(e.position))DrawEnemy(e);
            PlayerState player=Game.Player;SpriteRenderer hero=Show("hero",Game.IsElemental?PixelArt.ElementActor(player.element,player.moveDir,player.moving,player.dashTime,player.action,Game.Time,settings.reducedMotion):Game.Hero.id=="hoavi"?PixelArt.Hero(Game.Hero,player.moving?(int)(Game.Time*10)%4:0):PixelArt.WorldHero(Game.Hero,player,Game.Time,settings.reducedMotion),player.position,1,player.invulnerable>0&&Mathf.FloorToInt(Game.Time*12)%2==0?new Color(1,1,1,.6f):Color.white,Order(player.position));hero.flipX=Game.Hero.id=="hoavi"&&player.moveDir=="W";
            if(!Game.IsElemental&&!Game.IsShadow){V2 gunPosition=player.position+V2.Angle(player.facing)*.35f+new V2(0,.45f);SpriteRenderer gun=Show("held-weapon",PixelArt.Weapon(Game.Weapon),gunPosition,.85f,Color.white,Order(player.position)+2);gun.transform.rotation=Quaternion.Euler(0,0,player.facing*Mathf.Rad2Deg);gun.flipY=Mathf.Cos(player.facing)<0;}
            V2 pet=player.position+new V2(-.65f,Mathf.Sin(Game.Time*3)*.08f-.35f);Show("Đốm",PixelArt.Actor("fox",player.moving?"run":"idle",Game.Time,settings.reducedMotion),pet,1,Color.white,Order(pet));Loot secret=Game.Drops.Find(l=>!l.collected&&(l.kind=="chest"||l.kind=="memory")&&V2.Distance(l.position,player.position)<6);if(secret!=null)Ring("dom-guide",secret.position,.5f,new Color(1,.88f,.55f,.55f));
            for(int i=0;i<Game.Bullets.Count;i++){Bullet b=Game.Bullets[i];if(!InView(b.position))continue;SpriteRenderer bulletSprite=Show("bullet-"+i,b.kind=="shadow-crescent"?PixelArt.Shadow("shadow_crescent",Game.Time,settings.reducedMotion):b.kind=="code"?PixelArt.Weapon(content.Weapon("terminal")):PixelArt.Dot(),b.position,b.kind=="shadow-crescent"?1:b.kind=="code"?.25f:.7f,b.kind=="shadow-crescent"?Color.white:PixelArt.ColorOf(b.color),2500);bulletSprite.transform.rotation=Quaternion.Euler(0,0,Mathx.Angle(b.velocity)*Mathf.Rad2Deg);if(b.kind=="arrow")bulletSprite.transform.localScale=new Vector3(1.7f,.35f,1);}
            for(int i=0;i<Game.Dangers.Count;i++){Danger d=Game.Dangers[i];float progress=1-d.time/d.maxTime;Color col=PixelArt.ColorOf(d.color);Ring("danger-"+i,d.position,d.radius,col);Ring("danger-fill-"+i,d.position,d.radius*progress,new Color(col.r,col.g,col.b,.6f));Show("danger-glow-"+i,PixelArt.Glow(),d.position,d.radius*1.7f,new Color(col.r,col.g,col.b,.32f),-50);}
            for(int i=0;i<Game.Effects.Count;i++){Effect e=Game.Effects[i];if(e.kind=="text")continue;if(e.kind.StartsWith("world/")){string clip=e.kind.Substring(6);Show("world-fx-"+i,PixelArt.World(clip=="leaf_burst"?"ash_burst":clip,e.maxTime-e.time,settings.reducedMotion),e.position,1,Color.white,Order(e.position)+3);continue;}if(e.kind=="shadow"){bool ground=e.clip=="shadow_portal"||e.clip=="shadow_legion"||e.clip=="shadow_web"||e.clip=="shadow_roots";Show("shadow-fx-"+i,PixelArt.Shadow(e.clip,e.maxTime-e.time,settings.reducedMotion),e.position+new V2(0,(e.clip=="shadow_armor"?68:18)/64f),1,Color.white,ground?-850:Order(e.position)+3);continue;}if(e.kind=="element"){DrawElementEffect("element-fx-"+i,e);continue;}Color col=PixelArt.ColorOf(e.color);col.a*=e.time/e.maxTime;if(e.kind=="beam"){Ring("fx-beam-"+i,e.position,.05f,col);LineRenderer beam=lines["fx-beam-"+i];beam.positionCount=5;for(int k=0;k<5;k++){float f=k/4f;V2 pos=e.position+(e.end-e.position)*f;beam.SetPosition(k,new Vector3(pos.x,pos.y+(k%2==1?.12f:0),-.1f));}}
                else{Ring("fx-"+i,e.position,Mathf.Max(.05f,e.radius*(1-e.time/e.maxTime)),col);Show("fx-glow-"+i,PixelArt.Glow(),e.position,e.radius*1.6f,new Color(col.r,col.g,col.b,col.a*.3f),2000);}if(!playedFx.Contains(e)){playedFx.Add(e);if(e.kind=="ultimate"||e.kind=="circuit"||e.kind=="burst")Particles(e.position,e.radius,col);}}
            if(player.shield>0)Ring("shield",player.position+new V2(0,.55f),.75f,PixelArt.ColorOf("#c4b1ff"));if(player.firewall>0)Ring("firewall",player.position,2.4f,PixelArt.ColorOf("#eda9ef"));if(player.overclock>0)for(int i=0;i<2;i++){V2 at=player.position+V2.Angle(Game.Time*3+(i==0?-1:1))*.8f;Show("drone-"+i,PixelArt.Weapon(content.Weapon("compiler")),at,.45f,PixelArt.ColorOf("#7dffe6"),2000);}
            RenderElements();foreach(KeyValuePair<string,SpriteRenderer> pair in sprites)if(!visible.Contains(pair.Key))pair.Value.gameObject.SetActive(false);foreach(KeyValuePair<string,LineRenderer> pair in lines)if(!visible.Contains(pair.Key))pair.Value.gameObject.SetActive(false);if(playedFx.Count>500)playedFx.RemoveWhere(e=>!Game.Effects.Contains(e));
        }
        void Particles(V2 p,float radius,Color col){if(settings.reducedMotion)return;GameObject o=new GameObject("Skill sparks");o.transform.position=new Vector3(p.x,p.y,-.2f);ParticleSystem ps=o.AddComponent<ParticleSystem>();ParticleSystem.MainModule main=ps.main;main.duration=.6f;main.loop=false;main.startLifetime=.5f;main.startSpeed=Mathf.Min(6,radius*2);main.startSize=.07f;main.startColor=col;main.simulationSpace=ParticleSystemSimulationSpace.World;ParticleSystem.EmissionModule emission=ps.emission;emission.rateOverTime=0;ParticleSystem.ShapeModule shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Circle;shape.radius=.1f;ParticleSystemRenderer renderer=o.GetComponent<ParticleSystemRenderer>();Material pixels=new Material(material);pixels.mainTexture=PixelArt.Dot().texture;renderer.sharedMaterial=pixels;renderer.sortingOrder=3500;Destroy(pixels,1.5f);ps.Emit(26);Destroy(o,1.5f);}
        Sprite MakeGround(){if(terrain!=null){Destroy(terrain.texture);Destroy(terrain);}return PixelArt.Ground(Game.Seed);}
        AudioClip Tone(float frequency,float duration,float volume,bool sharp){int rate=22050,n=(int)(rate*duration);float[] data=new float[n];for(int i=0;i<n;i++){float at=i/(float)rate,envelope=Mathf.Min(1,at/.01f)*Mathf.Pow(1-at/duration,2);float wave=Mathf.Sin(at*frequency*Mathf.PI*2);if(sharp)wave+=Mathf.Sin(at*frequency*2*Mathf.PI*2)*.22f;data[i]=wave*envelope*volume;}AudioClip clip=AudioClip.Create("Đèn Tinh tone",n,1,rate,false);clip.SetData(data,0);return clip;}
        void Sfx(string kind){float f=kind=="codeShot"?880:kind=="shoot"?620:kind=="hurt"?130:kind=="dash"?380:kind=="kill"?190:kind=="pickup"?1100:kind=="ultimate"?330:720;AudioClip clip=Tone(f,kind=="ultimate"?.65f:.12f,kind=="shoot"||kind=="codeShot"?.12f:.2f,kind=="codeShot"||kind=="hurt");audioSource.PlayOneShot(clip);Destroy(clip,2);}
        void Music(float dt){if(Game.Paused||screen=="menu")return;string zone=Game.BossStarted&&!Game.Victory?"boss":Simulation.Zone(Game.Player.position);if(lastZone!=zone){lastZone=zone;musicTime=0;musicNote=0;}musicTime-=dt;if(musicTime>0)return;int[] tune=zone=="forest"?new[]{7,9,12,14,12,9,7,4}:zone=="lotus"?new[]{3,7,10,14,10,7,3,0}:zone=="ash"?new[]{0,3,5,7,5,3,0,2}:zone=="boss"?new[]{0,3,5,7,10,7,5,3}:new[]{0,4,7,9,12,9,7,4};musicSource.PlayOneShot(notes[tune[musicNote++%tune.Length]]);musicTime=zone=="boss"?.38f:zone=="forest"?.72f:1.05f;}
        void Styles(){if(stylesReady)return;stylesReady=true;text=new GUIStyle(GUI.skin.label){font=font,fontSize=20,wordWrap=true,richText=true};text.normal.textColor=PixelArt.ColorOf("#e9e4ce");small=new GUIStyle(text){fontSize=15};title=new GUIStyle(text){fontSize=42,fontStyle=FontStyle.Bold};button=new GUIStyle(GUI.skin.button){font=font,fontSize=20,wordWrap=true,padding=new RectOffset(16,16,8,8)};card=new GUIStyle(text){fontSize=18,padding=new RectOffset(18,18,14,14)};}
        void Panel(Rect r,Color? color=null){Color old=GUI.color;GUI.color=color??new Color(.045f,.095f,.14f,.94f);GUI.DrawTexture(r,Texture2D.whiteTexture);GUI.color=old;}
        bool Button(Rect r,string label){return GUI.Button(r,label,button);}
