        void RenderShadows(){
            foreach(ShadowRemain r in Game.ShadowRemains)if(InView(r.position))Show("soul-"+Game.ShadowRemains.IndexOf(r),PixelArt.Shadow("shadow_soul",Game.Time,settings.reducedMotion),r.position,1,Color.white,Order(r.position)+1);
            foreach(ShadowUnit s in Game.ShadowArmy)if(InView(s.position)){Show(s.id,PixelArt.Shadow((s.variant??s.kind)+"/"+(s.action==null?"walk":"attack"),s.action==null?Game.Time:s.action.elapsed,settings.reducedMotion),s.position,1,Color.white,Order(s.position));if(s.hp<s.maxHp){SpriteRenderer bar=Show(s.id+"-life",PixelArt.Dot(),s.position+new V2(0,-.1f),1,PixelArt.ColorOf("#b84dff"),Order(s.position)+1);bar.transform.localScale=new Vector3(3*s.hp/s.maxHp,.15f,1);}}
            if(Game.Player.shadowArmor>0)Show("shadow-armor",PixelArt.Shadow("shadow_armor",Game.Time,settings.reducedMotion),Game.Player.position+new V2(0,68/64f),1,Color.white,Order(Game.Player.position)+1);
        }
        void DrawHeld(string id,string form,V2 at,float aim,ActorAction action){
            string key="held_"+(form=="lightning"?"lightning_sword":form=="wind"?"wind_fan":form=="earth"?"earth_gauntlets":form=="ice"?"ice_hammer":form=="fire"?"fire_chakrams":form=="nature"?"nature_whip":"light_halo");float swing=action!=null&&action.key=="attack"&&!settings.reducedMotion?Mathf.Sin(Mathf.Clamp01(action.elapsed/action.duration)*Mathf.PI)*1.2f-.6f:0;Sprite image=PixelArt.Vfx(key,Game.Time,settings.reducedMotion);
            if(form=="light"){Show(id+"-held",image,at+new V2(0,.97f),1,Color.white,Order(at)-1);return;}
            if(form=="earth"||form=="fire"){for(int side=-1;side<=1;side+=2){SpriteRenderer r=Show(id+"-held-"+side,image,at+new V2(side*37/64f+(float)Math.Cos(aim+swing)*12/64f,44/64f+(float)Math.Sin(aim+swing)*12/64f),1,Color.white,Order(at)+2);r.transform.rotation=Quaternion.Euler(0,0,side*swing*Mathf.Rad2Deg);}return;}
            SpriteRenderer held=Show(id+"-held",image,at+new V2((float)Math.Cos(aim+swing)*51/64f,47/64f+(float)Math.Sin(aim+swing)*34/64f),1,Color.white,Order(at)+2);held.transform.rotation=Quaternion.Euler(0,0,(aim+swing)*Mathf.Rad2Deg);
        }
        void DrawElementEffect(string id,Effect e){
            float age=e.maxTime-e.time;Sprite sprite=PixelArt.Vfx(e.clip,age,settings.reducedMotion);V2 at=e.position;SpriteRenderer r=Show(id,sprite,at,1,Color.white,Order(at)+3);
            if(e.clip=="solar_beam"||e.clip=="chain_bolt"||e.clip=="vine_whip"||e.clip=="light_flash_step"){V2 d=e.end-at;r.transform.position=new Vector3((at.x+e.end.x)/2,(at.y+e.end.y)/2+.55f,0);r.transform.rotation=Quaternion.Euler(0,0,Mathx.Angle(d)*Mathf.Rad2Deg);r.transform.localScale=new Vector3(d.Length/Mathf.Max(.01f,sprite.bounds.size.x),e.clip=="solar_beam"?.875f/Mathf.Max(.01f,sprite.bounds.size.y):1,1);if(e.clip=="solar_beam")Show(id+"-prism",PixelArt.Vfx("solar_prism",age,settings.reducedMotion),at+new V2(0,.55f),1,Color.white,Order(at)+4);}
            else if(e.clip=="giant_vine")r.transform.rotation=Quaternion.Euler(0,0,e.angle*Mathf.Rad2Deg);
            if(e.clip=="split_matrix")for(int i=0;i<content.elements.Length;i++){float a=i*Mathf.PI*2/7;Show(id+"-crest-"+i,PixelArt.Vfx("crest_"+content.elements[i].id,age,settings.reducedMotion),at+new V2(Mathf.Cos(a)*1.75f,Mathf.Sin(a)*1.02f),1,Color.white,Order(at)+4);}
        }
        void LightTrail(string id,V2 at,float angle,float unit){if(settings.reducedMotion)return;for(int i=1;i<=3;i++){V2 point=at-V2.Angle(angle)*(i*.125f)+new V2(0,1.16f*unit);SpriteRenderer r=Show(id+"-eye-"+i,PixelArt.Dot(),point,1,PixelArt.ColorOf("#fffbe0"),Order(at)+1);r.transform.localScale=new Vector3(.5f*unit,.25f*unit,1);}}
        void RenderElements(){
            if(!Game.IsElemental)return;PlayerState p=Game.Player;DrawHeld("hero",p.element,p.position,p.aimAngle,p.action);if(p.element=="light"&&p.moving)LightTrail("player",p.position,p.moveFacing,1);if(p.hoverboard>0)Show("board-player",PixelArt.Vfx("hoverboard",Game.Time,settings.reducedMotion),p.position,1,Color.white,Order(p.position)-1);
            foreach(CloneState c in Game.Clones){if(!c.alive||!InView(c.position))continue;Show(c.id,PixelArt.ElementActor(c.element,c.moveDir,c.moving,c.dashTime,c.action,Game.Time,settings.reducedMotion),c.position,1,Color.white,Order(c.position));DrawHeld(c.id,c.element,c.position,c.aimAngle,c.action);if(c.element=="light"&&c.moving)LightTrail(c.id,c.position,c.moveFacing,1);if(c.hoverboard>0)Show(c.id+"-board",PixelArt.Vfx("hoverboard",Game.Time,settings.reducedMotion),c.position,1,Color.white,Order(c.position)-1);}
            foreach(SummonState s in Game.Summons){if(!InView(s.position))continue;string clip=s.kind=="golem"?(s.action!=null?"golem_smash":"golem_walk"):(s.action!=null?"treant_whip":"treant_walk");string pose=s.kind=="golem"?(s.action==null?"walk":s.action.clip.Substring(6)):(s.action==null?"walk":"attack");Show(s.id,PixelArt.Actor(s.kind,pose,s.action==null?Game.Time:s.action.elapsed,settings.reducedMotion),s.position,1,Color.white,Order(s.position));if(s.thrown!=null&&s.thrown.enemy==null)Show(s.id+"-rock",PixelArt.Vfx("golem_rock",s.thrown.elapsed,settings.reducedMotion),s.thrown.position+new V2(0,s.thrown.height),1,Color.white,Order(s.position)+4);SpriteRenderer bar=Show(s.id+"-life",PixelArt.Dot(),s.position+new V2(0,-.14f),1,PixelArt.ColorOf(s.kind=="golem"?"#ffcf82":"#78d663"),Order(s.position)+1);bar.transform.localScale=new Vector3(4*s.life/s.maxLife,.2f,1);}
            foreach(EnemyState e in Game.Enemies)if(e.alive&&InView(e.position)){if(e.frozen>0)Show(e.id+"-frozen",PixelArt.Vfx("freeze_cage",Game.Time,settings.reducedMotion),e.position+new V2(0,.4f),1,Color.white,Order(e.position)+2);if(e.rooted>0)Show(e.id+"-rooted",PixelArt.Vfx("vine_root",Game.Time,settings.reducedMotion),e.position,1,Color.white,Order(e.position)+3);}
            for(int i=0;i<Game.ElementFields.Count;i++){ElementField f=Game.ElementFields[i];string clip=f.behavior=="hurricane"?"tornado_hurricane":f.behavior=="tornado"?"tornado_mesh":f.behavior=="fire_breath"?"fire_breath":f.behavior=="blizzard"?"freeze_cage":f.behavior=="root"?"nature_garden":f.behavior=="meteor"?(f.delay>0?"giant_fireball":"meteor_burst"):f.behavior=="sword_array"?"lightning_swords":f.behavior=="lightning_prison"?"lightning_sigil":null;if(clip==null)continue;V2 at=f.position+new V2(0,clip=="tornado_mesh"?1.1f:0);if(f.behavior=="fire_breath")at+=V2.Angle(f.angle)*1.64f+new V2(0,.7f);SpriteRenderer r=Show("element-field-"+i,PixelArt.Vfx(clip,Game.Time,settings.reducedMotion),at,1,Color.white,Order(at)+1);if(f.behavior=="fire_breath")r.transform.rotation=Quaternion.Euler(0,0,f.angle*Mathf.Rad2Deg);}
            for(int i=0;i<Game.Bullets.Count;i++){Bullet b=Game.Bullets[i];if(b.element==null||!InView(b.position))continue;SpriteRenderer r=Show("bullet-"+i,PixelArt.Vfx("proj_"+b.element,Game.Time,settings.reducedMotion),b.position,1,Color.white,2500);r.transform.rotation=Quaternion.Euler(0,0,Mathx.Angle(b.velocity)*Mathf.Rad2Deg);}
        }
        static string ZoneName(string zone){return zone=="village"?"Làng Đèn":zone=="forest"?"Rừng Trúc":zone=="lotus"?"Đầm Sen":zone=="ash"?"Đồi Tro":zone=="ancient"?"Cội Đa Lạc Hồn":"Đường Gió";}
        static string Passive(string id){return id=="an"?"Nội tại · Ngọn Lửa Bền Bỉ":id=="linh"?"Nội tại · Nhịp Lá":id=="quanle"?"Nội tại · Linh Hồn Bóng Tối":"Nội tại · Mã Lệnh";}
        void Modal(){
            Panel(new Rect(0,0,1600,900),new Color(.015f,.025f,.055f,.7f));Rect box=new Rect(355,145,890,615);Panel(box,new Color(.06f,.12f,.18f,.98f));float x=390,y=178;GUI.Label(new Rect(x,y,810,65),screen=="talent"?"Chọn cách giữ lửa.":screen=="shop"?"Lò rèn Chú Bảy":screen=="inventory"?Game.Hero.name+" · Thuộc tính":screen=="map"?"Miền Sương Lạc":screen=="death"?"Đèn chưa tắt.":screen=="victory"?"Ngọn đèn tìm được đường về.":screen.Contains("settings")?"Âm thanh & điều khiển":screen=="pause"?"Nghỉ một nhịp.":"Ký ức của ngọn đèn",title);y+=75;
            if(screen=="split"){Label(new Rect(x,y,810,70),"Chọn 3 / 5 / 7 dạng. Giữ R 0,45s tách 7. X hợp thể; tuyệt kỹ dùng nút riêng.");int[] counts={3,5,7};for(int i=0;i<3;i++){int n=counts[i];if(Button(new Rect(x+i*270,y+90,250,95),n+" dạng · "+(n==3?30:n==5?45:60)+" linh lực")){Resume();Game.SplitElementals(n);}}if(Button(new Rect(x,y+220,810,65),"Tuyệt kỹ / Hợp kích · "+(int)Game.Player.ult+"%")){Resume();Game.Skill("r");}if(Button(new Rect(x,y+315,810,60),"Chọn nguyên tố"))Open("elements");if(Button(new Rect(x,y+395,810,55),"Tiếp tục"))Resume();return;}
            if(screen=="elements"){for(int i=0;i<content.elements.Length;i++){ElementDef e=content.elements[i];if(Button(new Rect(x+(i%4)*200,y+(i/4)*130,190,115),(i+1)+" · "+e.title+"\n"+e.q)){Game.TransformElement(e.id);Resume();}}if(Button(new Rect(x,y+350,810,60),"Tiếp tục"))Resume();return;}
            if(screen=="talent"){RelicDef[] choices=Game.Choices();for(int i=0;i<choices.Length;i++){RelicDef r=choices[i];if(Button(new Rect(x+i*275,y+30,255,280),r.icon+" "+r.name+"\n\n"+r.desc)){Game.ApplyRelic(r.id,true);Resume();}}return;}
            if(screen=="shop"){Label(new Rect(x,y,810,40),"Đang có "+Game.Player.gold+" xu · "+Game.Weapon.name+" +"+Game.Active.level);string[] ids={"weapon","relic","damage","hp","potion"},labels={"Nâng vũ khí · "+(55+Game.Active.level*30)+" xu","Di vật bí ẩn · 105 xu","+5 sát thương · "+(60+Game.Player.level*15)+" xu","+25 máu · "+(60+Game.Player.level*15)+" xu","Bình máu · 20 xu"};for(int i=0;i<ids.Length;i++)if(Button(new Rect(x+(i%2)*410,y+65+(i/2)*82,390,68),labels[i]))Game.Buy(ids[i]);if(Button(new Rect(x,y+340,810,58),"Lên đường"))Resume();return;}
            if(screen=="inventory"){PlayerState p=Game.Player;Label(new Rect(x,y,810,75),"Máu "+Math.Ceiling(p.hp)+"/"+p.maxHp+" · Linh lực "+(int)p.mp+"/"+p.maxMp+" · Giáp "+(int)(p.armor*100)+"%\n"+Passive(Game.Hero.id)+" · Ký ức "+Game.Memories.Count+"/3 · Thành tựu "+Game.Achievements.Count);for(int i=0;i<2;i++){WeaponState w=p.weapons[i];WeaponDef d=content.Weapon(w.id);Label(new Rect(x+i*410,y+85,390,100),"Ô "+(i+1)+" · "+d.name+" +"+w.level+"\n"+d.desc,true);}string list="";foreach(string r in p.relics){RelicDef d=content.Relic(r);if(d!=null)list+=d.name+" · ";}Label(new Rect(x,y+210,810,160),"DI VẬT\n"+(list==""?"Lên cấp, mở rương và đọc ký ức để tìm di vật.":list),true);if(Button(new Rect(x,y+395,810,55),"Tiếp tục"))Resume();return;}
            if(screen.Contains("settings")){Label(new Rect(x,y,400,35),"Âm lượng chung");settings.master=GUI.HorizontalSlider(new Rect(x+420,y+12,350,25),settings.master,0,1);Label(new Rect(x,y+60,400,35),"Nhạc theo vùng");settings.music=GUI.HorizontalSlider(new Rect(x+420,y+72,350,25),settings.music,0,1);Label(new Rect(x,y+120,400,35),"Âm thanh chiến đấu");settings.sfx=GUI.HorizontalSlider(new Rect(x+420,y+132,350,25),settings.sfx,0,1);Label(new Rect(x,y+180,400,35),"Cỡ chữ nhiệm vụ");settings.ui=GUI.HorizontalSlider(new Rect(x+420,y+192,350,25),settings.ui,1,1.4f);settings.reducedMotion=GUI.Toggle(new Rect(x,y+245,810,40),settings.reducedMotion," Giảm rung và hiệu ứng chớp",button);settings.touch=GUI.Toggle(new Rect(x,y+300,810,40),settings.touch," Điều khiển cảm ứng",button);if(Button(new Rect(x,y+380,810,58),"Lưu và đóng")){Directory.CreateDirectory(SaveFolder);File.WriteAllText(Path.Combine(SaveFolder,"settings.json"),JsonUtility.ToJson(settings,true));if(screen=="settings-menu"){screen="menu";Game.Paused=true;}else Resume();}return;}
            if(screen=="map"){Rect map=new Rect(x,y,810,380);Panel(map,new Color(.035f,.09f,.12f,1));foreach(Shrine s in Game.Shrines){Vector2 at=new Vector2(map.x+s.position.x/60*map.width,map.y+(1-s.position.y/45)*map.height);Label(new Rect(at.x-55,at.y-12,140,60),(s.active?"✦ ":"◇ ")+s.name,true);}V2 p=Game.Player.position;Label(new Rect(map.x+p.x/60*map.width-12,map.y+(1-p.y/45)*map.height-12,140,40),"● Bạn",true);Label(new Rect(map.x+310,map.y+35,200,35),"Cội Đa",true);if(Button(new Rect(x,y+400,810,55),"Đóng bản đồ"))Resume();return;}
            if(screen=="pause"){Label(new Rect(x,y,810,90),Game.Hero.name+" · Cấp "+Game.Player.level+" · "+Game.Kills+" quái\nẤn "+Game.Shrines.FindAll(s=>s.active).Count+"/3 · Hành trình +"+Game.Cycle);if(Button(new Rect(x,y+110,395,65),"Tiếp tục"))Resume();if(Button(new Rect(x+415,y+110,395,65),"Cài đặt"))Open("settings");if(Button(new Rect(x,y+195,395,65),"Lưu tiến độ")){Save();toast="Đã lưu hành trình.";toastTime=3;}if(Button(new Rect(x+415,y+195,395,65),"Lưu và về màn đầu")){Save();screen="menu";Game.Paused=true;}if(Button(new Rect(x,y+285,810,60),"Bỏ qua hướng dẫn đầu game")){Game.Tutorial=5;Resume();}return;}
            if(screen=="death"){Label(new Rect(x,y,810,170),"Đốm đưa bạn về Làng Đèn. Giữ vũ khí, di vật và các ấn đã thức tỉnh; mất 10% xu đang mang.");if(Button(new Rect(x,y+300,810,65),"Trở về Làng Đèn →")){Game.Respawn();Resume();}return;}
            if(screen=="victory"){Label(new Rect(x,y,810,220),"Cội đa cúi những cành già. Sương tan khỏi mái đình, khỏi giếng nước, khỏi bàn tay người đang đợi.\n\n"+Game.Hero.name+" · Cấp "+Game.Player.level+" · "+Game.Kills+" quái · "+Game.Deaths+" lần trở về\nHành trình hoàn thành trong "+(int)(Game.Time/60)+" phút.");if(Button(new Rect(x,y+285,810,65),"Tiếp tục khám phá"))Resume();if(Button(new Rect(x,y+365,810,65),"Hành trình + · thế giới mới"))NewGame(Game.Hero.id,Game.Cycle+1,true);return;}
            Label(new Rect(x,y,810,300),dialogue);if(Button(new Rect(x,y+365,810,65),"Mang đèn lên đường →")){if(screen=="help-menu"){screen="menu";Game.Paused=true;}else Resume();}
        }
        void TouchHud(){Panel(new Rect(40,650,160,160),new Color(.12f,.25f,.3f,.4f));Panel(new Rect(1390,650,160,160),new Color(.12f,.25f,.3f,.4f));Label(new Rect(50,815,180,35),"DI CHUYỂN",true);Label(new Rect(1400,815,180,35),"NGẮM / BẮN",true);if(Button(new Rect(1220,700,120,65),"F · Dùng"))Game.Interact();if(Button(new Rect(1220,780,120,65),"⇄ Đổi"))Game.Swap();}
    }
}
